import os
import sqlite3
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "default-secret-key")
DB_PATH = "db.sqlite3"


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS products (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                properties TEXT NOT NULL DEFAULT '{}'
            )
            """
        )
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_name ON products(name)")
        conn.commit()
    finally:
        conn.close()


init_db()


@app.route("/add", methods=["POST"])
def add_product():
    data = request.get_json(silent=True)
    if not data or not isinstance(data, dict):
        return jsonify({"error": "Invalid input"}), 400

    name = data.get("name")
    if not isinstance(name, str) or not name.strip():
        return jsonify({"error": "Invalid input"}), 400

    # Extract additional properties (everything except 'name')
    props = {k: v for k, v in data.items() if k != "name"}
    props_str = str(props)

    conn = get_db()
    try:
        # If product exists, update properties; otherwise insert
        existing = conn.execute(
            "SELECT properties FROM products WHERE name = ?", (name,)
        ).fetchone()
        if existing:
            conn.execute(
                "UPDATE products SET properties = ? WHERE name = ?",
                (props_str, name),
            )
        else:
            conn.execute(
                "INSERT INTO products (name, properties) VALUES (?, ?)",
                (name, props_str),
            )
        conn.commit()
    finally:
        conn.close()

    return jsonify({"status": "Product successfully added"}), 201


@app.route("/search", methods=["GET"])
def search_products():
    query = request.args.get("query", "")
    if not query:
        return jsonify({"error": "Invalid search query"}), 400

    query_lower = query.lower()
    conn = get_db()
    try:
        # Search in name and properties (stored as JSON string)
        rows = conn.execute(
            "SELECT id, name, properties FROM products WHERE LOWER(name) LIKE ? OR LOWER(properties) LIKE ?",
            (f"%{query_lower}%", f"%{query_lower}%"),
        ).fetchall()
    finally:
        conn.close()

    results = []
    for row in rows:
        product = {"name": row["name"]}
        try:
            props = eval(row["properties"]) if row["properties"] else {}
            if isinstance(props, dict):
                product.update(props)
            elif isinstance(props, list):
                product["items"] = props
        except Exception:
            pass
        results.append(product)

    return jsonify({"results": results}), 200


@app.route("/download", methods=["GET"])
def download_product():
    name = request.args.get("name", "")
    if not name:
        return jsonify({"error": "Invalid upload query"}), 400

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT properties FROM products WHERE name = ?", (name,)
        ).fetchone()
    finally:
        conn.close()

    if not row:
        return jsonify({"error": "Product not found"}), 404

    # Return the stored properties string as the "data" field
    return jsonify({"data": row["properties"]}), 200


@app.route("/upload", methods=["POST"])
def upload_product():
    data = request.get_json(silent=True)
    if not data or not isinstance(data, dict):
        return jsonify({"error": "Invalid upload query"}), 400

    name = data.get("name")
    data_val = data.get("data")

    if not isinstance(name, str) or not name.strip():
        return jsonify({"error": "Invalid upload query"}), 400
    if not isinstance(data_val, str):
        return jsonify({"error": "Invalid upload query"}), 400

    conn = get_db()
    try:
        existing = conn.execute(
            "SELECT id FROM products WHERE name = ?", (name,)
        ).fetchone()
        if existing:
            conn.execute(
                "UPDATE products SET properties = ? WHERE name = ?",
                (data_val, name),
            )
        else:
            conn.execute(
                "INSERT INTO products (name, properties) VALUES (?, ?)",
                (name, data_val),
            )
        conn.commit()
    finally:
        conn.close()

    return jsonify({"status": "Product with the given name was updated"}), 200


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
